function fewestInsertions(s: string): number {
  const go = (i: number, j: number): number => {
    if (i >= j) return 0;
    if (s[i] === s[j]) return go(i + 1, j - 1);
    return 1 + Math.min(go(i + 1, j), go(i, j - 1));
  };
  return go(0, s.length - 1);
}

