function fewestInsertions(s: string): number {
  const n = s.length;
  const dp = new Array(n).fill(0);
  for (let i = n - 2; i >= 0; i--) {
    let prev = 0; // dp[i+1][i], an empty slice
    for (let j = i + 1; j < n; j++) {
      const old = dp[j]; // dp[i+1][j]
      dp[j] = s[i] === s[j] ? prev : 1 + Math.min(old, dp[j - 1]);
      prev = old;
    }
  }
  return dp[n - 1];
}

