function fewestInsertions(s: string): number {
  const n = s.length;
  const t = s.split("").reverse().join("");
  let row = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    const next = new Array(n + 1).fill(0);
    for (let j = 1; j <= n; j++) {
      next[j] = s[i - 1] === t[j - 1] ? row[j - 1] + 1 : Math.max(row[j], next[j - 1]);
    }
    row = next;
  }
  return n - row[n];
}

